import{z as A,x as d,o as t,c as B,q as o,j as E,D as s,d as n,s as l,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"非易失内存与持久化","description":"","frontmatter":{"title":"非易失内存与持久化","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/nvm-persistent.md","filePath":"cs/nvm-persistent.md","lastUpdated":1791063341000}'),p={name:"cs/nvm-persistent.md"};function D(m,a,c,C,f,h){const r=d("Mermaid");return t(),B("div",null,[a[2]||(a[2]=o('<h1 id="非易失内存与持久化" tabindex="-1">非易失内存与持久化 <a class="header-anchor" href="#非易失内存与持久化" aria-label="Permalink to &quot;非易失内存与持久化&quot;">​</a></h1><div class="epigraph"><p>掉电仍在的介质可以挂在内存语义上，但写完成不等于持久：冲刷写队列、围栏与电源失效域，是另一套合同。</p><footer>—— 据 Hennessy and Patterson, CA:AQA；Intel/JEDEC 持久内存编程模型实践；Patterson and Hennessy, Computer Organization and Design 整理</footer></div><p><a href="/cs/hbm-3d-stack">上一课</a>仍是易失 DRAM。<a href="/cs/flash-memory">闪存对照</a>已说非易失不能当随机主存乱写。缺口是中间地带：<strong>字节可寻址持久内存</strong>（PCM、MRAM、3D XPoint 一类实践）挂在内存控制器上时，软件看见 load/store，崩溃一致性却要额外的冲刷。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DRAM 掉电即忘，文件系统靠磁盘/闪存的块接口和 <code>fsync</code>。把非易失 DIMM 映射进物理地址，CPU 缓存与内存控制器写缓冲仍可能在易失侧。缺口不是再讲行缓冲，而是：<strong>持久性域</strong>从哪条围栏/冲刷指令开始算「已到非易失介质」。ADR/eADR 一类平台承诺不同，本课钉问题，不背某代 Intel 指令助记符表。</p><p>写延迟往往高于读，调度器不能照搬纯 FR-FCFS 读优先而不考虑写队列爆。</p><p><span class="marginnote">常见误区：初学者容易以为「介质非易失，写完就安全」。实际上 store 先停在 CPU 缓存和写缓冲里，这些都在易失域，掉电时未冲刷的改动照样消失；只有冲刷加围栏之后，写才算越过分界线。</span></p><h3 id="持久内存不是「更快的-ssd」" tabindex="-1">持久内存不是「更快的 SSD」 <a class="header-anchor" href="#持久内存不是「更快的-ssd」" aria-label="Permalink to &quot;持久内存不是「更快的 SSD」&quot;">​</a></h3><p>SSD 走块与 FTL（下两课）。字节地址持久内存走 load/store，但没有 DRAM 的对称延迟，也没有磁盘的块接口自动保证。把 <code>clflush</code> 当 <code>fsync</code> 而不理解失效域，数据库恢复会错。本栏不把这写成量化交易日志课。</p><p><span class="marginnote">CA:AQA 讨论存储级内存。SNIA NVM 编程模型区分持久堆与文件。本课用系统课语言：缓存、写缓冲、围栏。不发明 arXiv 号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>软件：对持久对象更新、围栏、冲刷缓存行、再围栏。硬件：写结合缓冲要排空到持久域。掉电：电容把域内缓冲刷完（平台依赖）。ECC 与磨损：PCM 类有写磨损，控制器可能重映射，对软件可透明或暴露。</p>',12)),(t(),E(i,null,{default:s(()=>[l(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ST%5B%22store%22%5D%20--%3E%20CACHE%5B%22%E6%98%93%E5%A4%B1%E7%BC%93%E5%AD%98%20%2F%20%E5%86%99%E7%BC%93%E5%86%B2%22%5D%0A%20%20CACHE%20--%3E%20FLUSH%5B%22%E5%86%B2%E5%88%B7%E5%88%B0%E6%8C%81%E4%B9%85%E5%9F%9F%22%5D%0A%20%20FLUSH%20--%3E%20NVM%5B%22%E9%9D%9E%E6%98%93%E5%A4%B1%E9%98%B5%E5%88%97%22%5D%0A%20%20NVM%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9ANAND%20%E5%9D%97%E6%8E%A5%E5%8F%A3%E6%89%8D%E6%98%AF%20SSD%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 DRAM 通道可并存：易失主存 + 持久区，地址映射多分一段。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"数字实例：冲刷指令一次只管一条 64 字节缓存行。要把一整页 4 KB 的持久数据压实到介质，得冲刷 4096 ÷ 64 = 64 条缓存行，前后还要配围栏，这正是持久写比普通写慢一截的原因之一。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"下一课 NAND+FTL 是块设备主流实现，不提供 CPU 缓存行语义。本课防止把「非易失」三字在 HBM、闪存、持久 DIMM 之间划等号。fence 指令课在 ISA 对照会再遇到内存序，持久围栏是其超集需求。",-1)),a[7]||(a[7]=e("p",null,[e("span",{class:"marginnote"},"术语翻译：ADR（异步 DRAM 刷新）就是用平台备用电源在掉电瞬间把写队列里的数据自动刷进非易失介质；eADR 更进一步，把 CPU 缓存也划进保护域，软件要做的显式冲刷随之减少。")],-1)),(t(),E(i,null,{default:s(()=>[l(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%86%99%E6%8C%81%E4%B9%85%E5%AF%B9%E8%B1%A1%20P%22%5D%20--%3E%20F1%5B%22%E5%9B%B4%E6%A0%8F%20sfence%22%5D%0A%20%20F1%20--%3E%20FL%5B%22%E5%86%B2%E5%88%B7%E7%BC%93%E5%AD%98%E8%A1%8C%20clwb%22%5D%0A%20%20FL%20--%3E%20F2%5B%22%E5%86%8D%E5%9B%B4%E6%A0%8F%20sfence%22%5D%0A%20%20F2%20--%3E%20DONE%5B%22%E6%AD%A4%E5%88%BB%E8%B5%B7%E6%8E%89%E7%94%B5%E4%B9%9F%E4%B8%8D%E4%B8%A2%22%5D%0A%20%20W%20-.%20%E6%AD%A4%E5%88%BB%E6%8E%89%E7%94%B5%20.-%3E%20LOST%5B%22%E6%94%B9%E5%8A%A8%E4%BB%8D%E5%9C%A8%E6%98%93%E5%A4%B1%E7%BC%93%E5%AD%98%20%E6%81%A2%E5%A4%8D%E6%97%B6%E4%B8%A2%E5%A4%B1%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不保证某商用产品仍在市场，不写材料科学。不把文件系统日志算法写完。不进入光刻相变材料。</p><p>后课默认：字节持久内存要显式冲刷才能过崩溃；SSD 是另一条块接口路径。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>非易失阵列 ≠ 自动持久的 load/store。</li><li>缓存与写队列在易失域；围栏+冲刷定义持久点。</li><li>写慢、磨损、与 DRAM 异构共存。</li><li>出处：Hennessy and Patterson, CA:AQA；SNIA NVM 编程模型实践。</li></ul>',5))])}const P=A(p,[["render",D]]);export{S as __pageData,P as default};
